31	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidAddressException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.samples.petclinic.util.Households;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
111	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
112	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
113	        }
114	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
115	        rejectDuplicateTelephone(telephone);
116	        owner.setTelephone(telephone);
117	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
118	        if (owner.getRegistrationDate() == null) {
119	            owner.setRegistrationDate(java.time.LocalDate.now());
120	        }
121	        owner.setCustomerCode(assignCustomerCode(owner.getLastName()));
122	        this.clinicService.saveOwner(owner);
123	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
124	        headers.setLocation(UriComponentsBuilder.newInstance()
125	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
126	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
127	    }
128	
129	    /**
130	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'} where
131	     * LAST3 is the upper-cased first three letters of the last name and NNNN is a global 4-digit
132	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
133	     *
134	     * @param lastName the owner's last name
135	     * @return the assigned customer code
136	     */
137	    private String assignCustomerCode(String lastName) {
138	        String name = lastName == null ? "" : lastName;
139	        String last3 = name.substring(0, Math.min(3, name.length()))
140	            .toUpperCase(java.util.Locale.ROOT);
141	        int sequence = this.clinicService.findAllOwners().size() + 1;
142	        return String.format("%s-%04d", last3, sequence);
143	    }
144	
145	    /**
146	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
147	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
148	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
149	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
150	     * {@code "+61412345678"}. The E.164 value is stored and returned.
151	     *
152	     * @param telephone the raw telephone as submitted
153	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
154	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
155	     */
156	    private String normalizeTelephone(String telephone) {
157	        String raw = telephone == null ? "" : telephone.trim();
158	        boolean hasCountryCode = raw.startsWith("+");
159	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
160	        if (hasCountryCode) {
161	            cleaned = cleaned.substring(1);
162	        }
163	        String digits;
164	        if (hasCountryCode) {
165	            digits = cleaned;
166	        } else {
167	            if (cleaned.startsWith("0")) {
168	                cleaned = cleaned.substring(1);
169	            }
170	            digits = "61" + cleaned;
171	        }
172	        if (!digits.matches("[0-9]{8,15}")) {
173	            throw new InvalidTelephoneException(telephone);
174	        }
175	        return "+" + digits;
176	    }
177	
178	    /**
179	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
180	     * multi-character top-level label. Deliberately lenient about the exact character set while still
181	     * rejecting values that are clearly not addresses (e.g. missing '@').
182	     */
183	    private static final java.util.regex.Pattern EMAIL_PATTERN =
184	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
185	
186	    /**
187	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
188	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
189	     * lower-cased before being stored and returned.
190	     *
191	     * @param email the raw email as submitted, may be {@code null}
192	     * @return the lower-cased email, or {@code null} when none was supplied
193	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
194	     */
195	    private String normalizeEmail(String email) {
196	        if (email == null || email.isBlank()) {
197	            return null;
198	        }
199	        String trimmed = email.trim();
200	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
201	            throw new InvalidEmailException(email);
202	        }
203	        return trimmed.toLowerCase(java.util.Locale.ROOT);
204	    }
205	
206	    /**
207	     * Common street-type abbreviations expanded to their full word during address normalization.
208	     */
209	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
210	        "ST", "STREET",
211	        "RD", "ROAD",
212	        "AVE", "AVENUE");
213	
214	    /**
215	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
216	     * whitespace collapse to a single space, the value is upper-cased and common street-type
217	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
218	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
219	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
220	     * for every address comparison (household duplicate detection and the shared household id).
221	     *
222	     * @param address the raw address as submitted
223	     * @return the normalized address
224	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
225	     */
226	    private String normalizeAddress(String address) {
227	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
228	        if (collapsed.isEmpty()) {
229	            throw new InvalidAddressException(address);
230	        }
231	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
232	        StringBuilder normalized = new StringBuilder(collapsed.length());
233	        for (int i = 0; i < tokens.length; i++) {
234	            if (i > 0) {
235	                normalized.append(' ');
236	            }
237	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
238	        }
239	        return normalized.toString();
240	    }
241	
242	    /**
243	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
244	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
245	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
246	     * {@code "+61 412 345 678"}) are still treated as duplicates.
247	     *
248	     * @param telephone the E.164 telephone of the owner being created
249	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
250	     */
251	    private void rejectDuplicateTelephone(String telephone) {
252	        boolean duplicate = this.clinicService.findAllOwners().stream()
253	            .map(Owner::getTelephone)
254	            .filter(existing -> existing != null)
255	            .map(this::toE164OrNull)
256	            .filter(existing -> existing != null)
257	            .anyMatch(telephone::equals);
258	        if (duplicate) {
259	            throw new DuplicateTelephoneException(telephone);
260	        }
261	    }
262	
263	    /**
264	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
265	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number.
266	     */
267	    private String toE164OrNull(String telephone) {
268	        try {
269	            return normalizeTelephone(telephone);
270	        } catch (InvalidTelephoneException e) {
271	            return null;
272	        }
273	    }
274	
275	    /**
276	     * Rejects creating an owner who shares a household with an existing owner, i.e. another owner
277	     * already has the same last name and the same address. Last names are compared case-insensitively
278	     * with whitespace collapsed; addresses are compared in their normalized form (see
279	     * {@link #normalizeAddress}, which every owner's stored address already uses), so values that
280	     * differ only in letter case, spacing or a common street-type abbreviation still count as a match.
281	     * This check is skipped when the request sets {@code sharesHousehold} to {@code true}.
282	     *
283	     * @param lastName the last name of the owner being created
284	     * @param address the normalized address of the owner being created
285	     * @throws DuplicateHouseholdException (409 Conflict) if another owner shares this household
286	     */
287	    private void rejectDuplicateHousehold(String lastName, String address) {
288	        String normalizedLastName = Households.normalize(lastName);
289	        String normalizedAddress = Households.normalize(address);
290	        boolean duplicate = this.clinicService.findAllOwners().stream()
291	            .anyMatch(existing ->
292	                Households.normalize(existing.getLastName()).equals(normalizedLastName)
293	                    && Households.normalize(existing.getAddress()).equals(normalizedAddress));
294	        if (duplicate) {
295	            throw new DuplicateHouseholdException(lastName, address);
296	        }
297	    }
298	
299	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
300	    @Override
301	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
302	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
303	        if (currentOwner == null) {
304	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
305	        }
306	        currentOwner.setAddress(ownerFieldsDto.getAddress());
307	        currentOwner.setCity(ownerFieldsDto.getCity());
308	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
309	        currentOwner.setLastName(ownerFieldsDto.getLastName());
310	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
311	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
312	        this.clinicService.saveOwner(currentOwner);
313	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
314	    }
315	
316	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
317	    @Transactional
318	    @Override
319	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
320	        Owner owner = this.clinicService.findOwnerById(ownerId);
321	        if (owner == null) {
322	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
323	        }
324	        this.clinicService.deleteOwner(owner);
325	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
326	    }
327	
328	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
329	    @Override
330	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
331	        Owner owner = this.clinicService.findOwnerById(ownerId);
332	        if (owner == null) {
333	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
334	        }
335	        HttpHeaders headers = new HttpHeaders();
336	        Pet pet = petMapper.toPet(petFieldsDto);
337	        owner.setId(ownerId);
338	        pet.setOwner(owner);
339	        pet.getType().setName(null);
340	        this.clinicService.savePet(pet);
341	        PetDto petDto = petMapper.toPetDto(pet);
342	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
343	            .buildAndExpand(pet.getId()).toUri());
344	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
345	    }
346	
347	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
348	    @Override
349	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
350	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
351	        if (currentOwner != null) {
352	            Pet currentPet = this.clinicService.findPetById(petId);
353	            if (currentPet != null) {
354	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
355	                currentPet.setName(petFieldsDto.getName());
356	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
357	                this.clinicService.savePet(currentPet);
358	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
359	            }
360	        }
361	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
362	    }
363	
364	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
365	    @Override
366	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
367	        HttpHeaders headers = new HttpHeaders();
368	        Visit visit = visitMapper.toVisit(visitFieldsDto);
369	        Pet pet = new Pet();
370	        pet.setId(petId);
371	        visit.setPet(pet);
372	        this.clinicService.saveVisit(visit);
373	        VisitDto visitDto = visitMapper.toVisitDto(visit);
374	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
375	            .buildAndExpand(visit.getId()).toUri());
376	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
377	    }
378	
379	
380	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
381	    @Override
382	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
383	        Owner owner = this.clinicService.findOwnerById(ownerId);
384	        if (owner != null) {
385	            Pet pet = owner.getPet(petId);
386	            if (pet != null) {
387	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
388	            }
389	        }
390	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
391	    }
392	}
