152	     */
153	    public Pet getPet(String name, boolean ignoreNew) {
154	        name = name.toLowerCase();
155	        for (Pet pet : getPetsInternal()) {
156	            if (!ignoreNew || !pet.isNew()) {
157	                String compName = pet.getName();
158	                compName = compName.toLowerCase();
159	                if (compName.equals(name)) {
160	                    return pet;
161	                }
162	            }
163	        }
